  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "हर कर्मचारी के लिए है। हर वेब पंच के लिए स्वीकृत फेस आईडी से लाइव फेस मिलान आवश्यक है; जब तक फेस आईडी नहीं बनती, वेब क्लॉक-इन/आउट अवरुद्ध रहता है, जब तक कि आप नीचे दिया गया विकल्प न चुनें।",
