  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "कर्मचारी कितने दिन पीछे तक घर से काम का अनुरोध कर सकता है। अनुमति नहीं (अनुशंसित): केवल आज या बाद की तारीख, क्योंकि बीते दिन का स्वीकृत अनुरोध उस दिन को बाद में बदल देता है और घर के स्थान की जाँच पूरी नहीं की जा सकती।",
