  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "इस खाते का कोई कर्मचारी रिकॉर्ड नहीं है (कोई कर्मचारी संख्या नहीं दी गई), इसलिए नीचे रोज़गार, वेतन, वैधानिक और इतिहास का विवरण उपलब्ध नहीं है। जिस एडमिन/सिस्टम लॉगिन को कर्मचारी के रूप में कभी ऑनबोर्ड नहीं किया गया, उसके लिए यह अपेक्षित है — पूरा रिकॉर्ड देखने के लिए ऑनबोर्ड किए गए कर्मचारी के रूप में साइन इन करें।",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "इस कर्मचारी ने बैंक विवरण में बदलाव जमा किया है जो आपकी समीक्षा की प्रतीक्षा में है — आपके निर्णय तक पेरोल के लिए उनका पिछला विवरण ही सक्रिय रहेगा।",
  "UAN": "UAN",
  "Click to choose the filled .xlsx file": "भरी हुई .xlsx फ़ाइल चुनने के लिए क्लिक करें",
  "Confirm import of {count}": "{count} के आयात की पुष्टि करें",
  "Confirm.": "पुष्टि करें।",
  "Download errors (Excel)": "त्रुटियाँ डाउनलोड करें (Excel)",
  "Download template (.xlsx)": "टेम्पलेट डाउनलोड करें (.xlsx)",
  "Download the template and fill it in.": "टेम्पलेट डाउनलोड करें और उसे भरें।",
  "Each new employee then gets an activation email.": "फिर प्रत्येक नए कर्मचारी को एक सक्रियण ईमेल मिलता है।",
  "Every row must be valid to start.": "शुरू करने के लिए हर पंक्ति मान्य होनी चाहिए।",
  "Everything is valid. Press Confirm to create these employees.": "सब कुछ मान्य है। इन कर्मचारियों को बनाने के लिए पुष्टि करें दबाएँ।",
  "Fix the rows below (or download the error file), then upload again. Nothing has been created.": "नीचे की पंक्तियाँ ठीक करें (या त्रुटि फ़ाइल डाउनलोड करें), फिर दोबारा अपलोड करें। कुछ भी नहीं बनाया गया है।",
  "Import another file": "दूसरी फ़ाइल आयात करें",
  "Import Employees from Excel": "Excel से कर्मचारी आयात करें",
  "Starting…": "शुरू हो रहा है…",
  "The employees are then created in the background, so you can close this window and come back: progress is saved.": "इसके बाद कर्मचारी पृष्ठभूमि में बनाए जाते हैं, इसलिए आप यह विंडो बंद करके बाद में लौट सकते हैं: प्रगति सहेजी रहती है।",
  "Upload it and review the preview — nothing is created yet.": "इसे अपलोड करें और पूर्वावलोकन देखें — अभी कुछ नहीं बनाया जाता।",
  "You can import into:": "आप इनमें आयात कर सकते हैं:",
  "{count} day — weekly offs (Saturday and Sunday) excluded.": "{count} दिन — साप्ताहिक अवकाश (शनिवार और रविवार) शामिल नहीं।",
