  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "कर्मचारी को इस कैमरे के सामने बैठाएँ, फिर शुरू करें — सहेजने से पहले एक त्वरित लाइवनेस जाँच पुष्टि करती है कि वही व्यक्ति है।",
