  "Register Face ID — {name}": "Face ID पंजीकृत करें — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID पंजीकृत करने के लिए कैमरा एक्सेस चाहिए। अपने ब्राउज़र की सेटिंग्स में इस साइट के लिए अनुमति दें, फिर कोशिश करें।",
  "Registering face ID…": "Face ID पंजीकृत हो रही है…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "पंजीकरण के लिए स्वाभाविक पलक झपकना और हल्का सिर घुमाना दोनों चाहिए, और हम समय पर दोनों नहीं देख सके। सुनिश्चित करें कि रोशनी अच्छी हो और चेहरा बीच में हो, फिर कोशिश करें।",
