  "Update Face ID — {name}": "Face ID अपडेट करें — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "हमें भरोसेमंद रूप से स्पष्ट कैप्चर नहीं मिल सका — यही उनकी स्थायी Face ID संदर्भ बनेगा, इसलिए इसे सही लेना ज़रूरी है। बेहतर रोशनी में कोशिश करें और उन्हें स्थिर रहने को कहें।",
  "Contact an HR administrator if you believe this is a mistake.": "यदि आपको लगता है कि यह गलती है तो किसी एचआर एडमिन से संपर्क करें।",
