  "The draft and everything entered so far will be deleted, and its reserved employee number is released. This cannot be undone. To keep it, use Save & exit instead.": "ड्राफ़्ट और अब तक दर्ज सब कुछ हटा दिया जाएगा, और उसकी आरक्षित कर्मचारी संख्या मुक्त हो जाएगी। इसे वापस नहीं किया जा सकता। इसे रखने के लिए इसके बजाय \"सहेजें और बाहर निकलें\" का उपयोग करें।",
  "The new hire": "नया कर्मचारी",
  "The server did not keep: {fields}. Nothing was hired. Open that step, re-enter it, wait for \"Saved\", and press Hire again.": "सर्वर ने ये नहीं रखे: {fields}। कोई नियुक्ति नहीं हुई। वह चरण खोलें, दोबारा दर्ज करें, \"सहेजा गया\" दिखने तक प्रतीक्षा करें और फिर नियुक्ति दबाएँ।",
  "Type the first and last name first. Suggest builds the display name from them.": "पहले नाम और उपनाम लिखें। \"सुझाएँ\" उनसे प्रदर्शित नाम बनाता है।",
  "You will need to upload it again before hiring.": "नियुक्ति से पहले आपको इसे दोबारा अपलोड करना होगा।",
  "Your entries could not be saved, so nothing was hired. {message}": "आपकी प्रविष्टियाँ सहेजी नहीं जा सकीं, इसलिए कोई नियुक्ति नहीं हुई। {message}",
