  "The new hire registers their Face ID from their Profile page, and HR approves it on": "नया कर्मचारी अपनी प्रोफ़ाइल पृष्ठ से Face ID पंजीकृत करता है, और एचआर इसे यहाँ स्वीकृत करता है:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "नया कर्मचारी अपनी प्रोफ़ाइल पृष्ठ से अपनी Face ID स्वयं पंजीकृत करता है; यह तुरंत सक्रिय हो जाती है।",
  "the record can still be created in Onboarding status.": "रिकॉर्ड फिर भी ऑनबोर्डिंग स्थिति में बनाया जा सकता है।",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "रिकॉर्ड ऑनबोर्डिंग स्थिति में बनाया जाता है। वैकल्पिक विवरण (पिता/माता का नाम, गैर-आवश्यक दस्तावेज़) बाद में भी पूरे किए जा सकते हैं।",
  "Until it is done they cannot clock in on the web.": "जब तक यह नहीं होता, वे वेब पर क्लॉक-इन नहीं कर सकते।",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "तब तक वे ऑफिस से क्लॉक-इन कर सकते हैं; उन पंचों को एचआर के लिए चिह्नित किया जाता है।",
  "Apply selected": "चुने हुए लागू करें",
  "Choose a PDF, JPG or PNG": "PDF, JPG या PNG चुनें",
  "Could not scan this document. Please try again.": "यह दस्तावेज़ स्कैन नहीं हो सका। कृपया फिर कोशिश करें।",
  "FOUND IN DOCUMENT": "दस्तावेज़ में मिला",
