  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "टीम प्रबंधक चालू करने पर नीचे की सामान्य प्रबंधक अनुमतियाँ (कर्मचारी देखें, छुट्टी स्वीकृत करें, उपस्थिति देखें) भी चुन ली गईं ताकि इस पद के पास 0 अनुमतियाँ न रहें। सहेजने से पहले जो न चाहिए उन्हें अनचेक करें।",
