  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} कर्मचारियों के लिए वेतन ट्रांसफ़र लॉक हो गया। पेरोल को भुगतान किया गया चिह्नित करने से पहले NEFT CSV डाउनलोड करके अपने बैंक में जमा करें।",
  "Salary transfer readiness is unavailable.": "वेतन ट्रांसफ़र की तैयारी की जानकारी उपलब्ध नहीं है।",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "यह सभी {count} कर्मचारियों के वर्तमान बैंक विवरण और निवल वेतन को एक ट्रांसफ़र बैच में लॉक कर देता है। पुष्टि के बाद NEFT CSV डाउनलोड करें और पेरोल को भुगतान किया गया चिह्नित करने से पहले इसे अपने बैंक के माध्यम से जमा करें।",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "यह सभी {count} वेतन पर्ची (कुल {amount}) को भुगतान किया गया चिह्नित करता है और इस पेरोल रन को बंद कर देता है। यह स्वयं पैसे ट्रांसफ़र नहीं करता — यह दर्ज करता है कि ट्रांसफ़र पहले ही हो चुका है। इसे पूर्ववत नहीं किया जा सकता।",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "यह सभी {count} वेतन पर्चियों (कुल {amount}) को भुगतान किया गया चिह्नित करता है और इस पेरोल रन को बंद कर देता है। यह स्वयं पैसे ट्रांसफ़र नहीं करता — यह दर्ज करता है कि ट्रांसफ़र पहले ही हो चुका है। इसे पूर्ववत नहीं किया जा सकता।",
  "Total Net Payable": "कुल निवल देय",
