  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "यह इस चक्र के सभी {count} कर्मचारियों का वेतन शुरू से दोबारा गणना करता है और मौजूदा आँकड़ों को बदल देता है — इन वेतन पर्चियों पर पहले से किए गए मैन्युअल बोनस या प्रतिपूर्ति समायोजन भी इसमें शामिल हैं। इसे पूर्ववत नहीं किया जा सकता।",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "यह सभी पात्र कर्मचारियों का वेतन उनके CTC, वेतन संरचना और प्रत्येक शाखा के वैधानिक नियमों के आधार पर गणना करेगा।",
