  "Generate a report, download it, or email it to a colleague. You only see reports you are allowed to run, and each one contains only the people and records you are allowed to see.": "रिपोर्ट बनाएँ, डाउनलोड करें या किसी सहकर्मी को ईमेल करें। आपको केवल वही रिपोर्ट दिखती हैं जिन्हें चलाने की आपको अनुमति है, और हर रिपोर्ट में केवल वही लोग और रिकॉर्ड होते हैं जिन्हें देखने की आपको अनुमति है।",
  "Loading reports…": "रिपोर्ट लोड हो रही हैं…",
  "No reports are available to you": "आपके लिए कोई रिपोर्ट उपलब्ध नहीं है",
  "Other report screens": "अन्य रिपोर्ट स्क्रीन",
  "Reports appear here when your role gives you access to the data they cover.": "जब आपकी भूमिका आपको उनके डेटा का एक्सेस देती है तब रिपोर्ट यहाँ दिखाई देती हैं।",
  "Comment": "टिप्पणी",
