  "Other Adjustment: {amount}": "अन्य समायोजन: {amount}",
  "Pro-rata Salary": "आनुपातिक वेतन",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "आनुपातिक वेतन, छुट्टी नकदीकरण और नोटिस अवधि की कमी अपने-आप गणना की जाती है (CTC ÷ 30, अर्जित छुट्टी शेष) — यह समीक्षा के लिए प्रारंभिक अनुमान है, अंतिम आँकड़ा नहीं। ग्रेच्युटी, बोनस, प्रतिपूर्ति, अग्रिम और TDS हमेशा हाथ से दर्ज किए जाते हैं।",
  "Settlement finalized.": "निपटान को अंतिम रूप दे दिया गया।",
  "Settlement updated.": "निपटान अपडेट हो गया।",
  "This is a recovery — the employee owes the company (net payable may be negative)": "यह वसूली है — कर्मचारी पर कंपनी का बकाया है (निवल देय ऋणात्मक हो सकता है)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "यह पूर्ण और अंतिम निपटान को {amount} की निवल देय राशि पर लॉक कर देता है। अंतिम रूप देने के बाद इस निपटान का कोई भी फ़ील्ड — ग्रेच्युटी, बोनस, प्रतिपूर्ति, अग्रिम, TDS या समायोजन — दोबारा संपादित नहीं किया जा सकता। इसे पूर्ववत नहीं किया जा सकता।",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "यह पूर्ण और अंतिम निपटान को कर्मचारी से {amount} की निवल वसूली योग्य राशि पर लॉक कर देता है। अंतिम रूप देने के बाद इस निपटान का कोई भी फ़ील्ड — ग्रेच्युटी, बोनस, प्रतिपूर्ति, अग्रिम, TDS या समायोजन — दोबारा संपादित नहीं किया जा सकता। इसे पूर्ववत नहीं किया जा सकता।",
