  "This CIN's listing prefix (L) marks it as a listed company, which isn't possible for this entity type.": "इस CIN का सूचीकरण उपसर्ग (L) इसे सूचीबद्ध कंपनी दर्शाता है, जो इस संस्था प्रकार के लिए संभव नहीं है।",
