  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "नीचे किसी भी पंक्ति पर फ़ाइल खींचकर छोड़ें, या अपलोड पर क्लिक करें। स्वीकार्य: PDF, JPG, PNG · प्रत्येक अधिकतम 5 MB।",
