  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "आपके संगठन में वेब क्लॉक-इन/आउट के लिए पंजीकृत Face ID आवश्यक है। यहाँ एक बार पंजीकरण करें — यह पुष्टि करने के लिए कि वह वास्तव में आप ही हैं, हम एक त्वरित लाइवनेस जाँच करते हैं, और यह तुरंत प्रभावी हो जाता है।",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "आपके संगठन में वेब क्लॉक-इन/आउट के लिए पंजीकृत Face ID आवश्यक है। यहाँ एक बार पंजीकरण करें — यह पुष्टि करने के लिए कि वह वास्तव में आप ही हैं, हम एक त्वरित लाइवनेस जाँच करते हैं, फिर उसे स्वीकृति के लिए HR को भेजते हैं।",
