  "Fill in your details to get started. Your information is kept secure.": "शुरू करने के लिए अपनी जानकारी भरें। आपकी जानकारी सुरक्षित रखी जाती है।",
  "HR has approved your onboarding.": "एचआर ने आपका ऑनबोर्डिंग स्वीकृत कर दिया है।",
