  "Name is required for every family member — remove any blank ones, or fill them in.": "हर परिवार सदस्य के लिए नाम आवश्यक है — खाली प्रविष्टियाँ हटाएँ या उन्हें भरें।",
  "Not saved yet. Check your connection; Save & Continue will retry": "अभी सहेजा नहीं गया। अपना कनेक्शन जाँचें; \"सहेजें और आगे बढ़ें\" दोबारा कोशिश करेगा",
  "Please fill in: {fields}": "कृपया भरें: {fields}",
  "Please review and resubmit — contact HR for details.": "कृपया समीक्षा करके दोबारा जमा करें — विवरण के लिए एचआर से संपर्क करें।",
  "Profile Submitted!": "प्रोफ़ाइल जमा हो गई!",
  "Save Draft": "ड्राफ़्ट सहेजें",
  "Saved successfully.": "सफलतापूर्वक सहेजा गया।",
  "Select a family member for every nominee — remove any incomplete ones, or fill them in.": "हर नामित व्यक्ति के लिए एक परिवार सदस्य चुनें — अधूरी प्रविष्टियाँ हटाएँ या उन्हें भरें।",
  "Select an asset type for every entry — remove any incomplete ones, or fill them in.": "हर प्रविष्टि के लिए संपत्ति का प्रकार चुनें — अधूरी प्रविष्टियाँ हटाएँ या उन्हें भरें।",
  "Still awaiting HR review — check back later, or wait for the email notification.": "अभी एचआर समीक्षा लंबित है — बाद में देखें, या ईमेल सूचना की प्रतीक्षा करें।",
  "We have emailed you a link to set your password and activate your account.": "हमने आपको पासवर्ड सेट करने और खाता सक्रिय करने के लिए एक लिंक ईमेल किया है।",
  "You can close this tab and continue from the email.": "आप यह टैब बंद करके ईमेल से आगे बढ़ सकते हैं।",
