  "You will receive access once approved.": "स्वीकृत होने के बाद आपको एक्सेस मिल जाएगा।",
  "Your onboarding details have been sent for HR review.": "आपके ऑनबोर्डिंग विवरण एचआर समीक्षा के लिए भेज दिए गए हैं।",
  "Opening your onboarding…": "आपका ऑनबोर्डिंग खुल रहा है…",
  "This link can't be used": "यह लिंक उपयोग नहीं किया जा सकता",
  "Ask HR to reset your password again, or": "एचआर से अपना पासवर्ड दोबारा रीसेट करने को कहें, या",
  "Checking your reset link…": "आपका रीसेट लिंक जाँचा जा रहा है…",
  "Log in with your new password to continue.": "आगे बढ़ने के लिए अपने नए पासवर्ड से लॉग इन करें।",
  "Password set": "पासवर्ड सेट हो गया",
  "Set new password": "नया पासवर्ड सेट करें",
  "Setting password…": "पासवर्ड सेट हो रहा है…",
  "This reset link is invalid or has expired.": "यह रीसेट लिंक अमान्य है या समाप्त हो चुका है।",
  "Your password was reset by HR. Set a new one to continue signing in as": "आपका पासवर्ड एचआर ने रीसेट कर दिया है। इस रूप में साइन इन जारी रखने के लिए नया पासवर्ड सेट करें:",
  "Choose someone only if L1 should differ from what the approval rule gives.": "किसी को तभी चुनें जब L1 स्वीकृति नियम से मिलने वाले व्यक्ति से अलग होना चाहिए।",
  "Could not load the list of people. Try again in a moment.": "लोगों की सूची लोड नहीं हो सकी। थोड़ी देर में फिर कोशिश करें।",
