  "{count} employees have no joining date. They are left out of attendance and payroll until HR corrects it.": "{count} कर्मचारियों की कोई जॉइनिंग तिथि नहीं है। एचआर के सुधारने तक वे उपस्थिति और पेरोल से बाहर रहेंगे।",
