  "Blink ✓ — now turn your head slightly": "पलक झपकाई ✓ — अब सिर को थोड़ा घुमाएँ",
  "Head turn ✓ — now blink naturally": "सिर घुमाया ✓ — अब सामान्य रूप से पलक झपकाएँ",
  "Make sure you place your face inside the frame": "सुनिश्चित करें कि आपका चेहरा फ़्रेम के अंदर हो",
  "Slowly turn your head slightly to one side, then back": "धीरे से सिर को थोड़ा एक ओर घुमाएँ, फिर वापस लाएँ",
