  "I Agree & Continue": "मैं सहमत हूँ और आगे बढ़ें",
  "I have read and agree to the above.": "मैंने ऊपर दिया गया पढ़ लिया है और मैं सहमत हूँ।",
  "Face ID registration was rejected": "फेस आईडी पंजीकरण अस्वीकृत हो गया",
  "Face ID waiting for approval": "फेस आईडी स्वीकृति की प्रतीक्षा में",
  "Register your Face ID": "अपना फेस आईडी पंजीकृत करें",
  "Couldn't confirm you're live": "पुष्टि नहीं हो सकी कि आप लाइव हैं",
  "Face registration needs your camera. Allow camera access for this site in your browser's settings, then try again.": "चेहरे के पंजीकरण के लिए आपके कैमरे की आवश्यकता है। अपने ब्राउज़र की सेटिंग्स में इस साइट के लिए कैमरा एक्सेस की अनुमति दें, फिर फिर कोशिश करें।",
  "Register your face": "अपना चेहरा पंजीकृत करें",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure you're well-lit and centered, then try again.": "पंजीकरण के लिए सामान्य पलक झपकना और सिर का हल्का घुमाव दोनों ज़रूरी हैं, और हमें समय पर दोनों नहीं दिखे। सुनिश्चित करें कि पर्याप्त रोशनी हो और आप फ़्रेम के बीच में हों, फिर फिर कोशिश करें।",
  "Registration submitted!": "पंजीकरण जमा हो गया!",
  "Sending your registration for approval…": "आपका पंजीकरण स्वीकृति के लिए भेजा जा रहा है…",
  "Submitting": "जमा हो रहा है",
  "Update your face ID": "अपना फेस आईडी अपडेट करें",
  "We couldn't get a reliably clear capture — this becomes your permanent face ID reference, so it's worth getting right. Try better lighting and hold steady.": "हमें भरोसेमंद रूप से साफ़ कैप्चर नहीं मिल सका — यही आपका स्थायी फेस आईडी संदर्भ बनेगा, इसलिए इसे सही करना ज़रूरी है। बेहतर रोशनी में कोशिश करें और स्थिर रहें।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "हम कैमरा एक्सेस माँगेंगे, यह पुष्टि करने के लिए एक त्वरित लाइवनेस जाँच (एक पलक झपकना और सिर का हल्का घुमाव) चलाएँगे कि वाकई आप ही हैं, फिर आपका फेस आईडी एचआर स्वीकृति के लिए भेजेंगे। कोई फ़ोटो या वीडियो कभी नहीं भेजा जाता — केवल एक संख्यात्मक चेहरा हस्ताक्षर।",
  "We'll ask for camera access, run a quick liveness check (a blink and a slight head turn) to confirm it's really you, then send your updated face ID for HR approval. No photo or video is ever sent — only a numeric face signature.": "हम कैमरा एक्सेस माँगेंगे, यह पुष्टि करने के लिए एक त्वरित लाइवनेस जाँच (एक पलक झपकना और सिर का हल्का घुमाव) चलाएँगे कि वाकई आप ही हैं, फिर आपका अपडेट किया गया फेस आईडी एचआर स्वीकृति के लिए भेजेंगे। कोई फ़ोटो या वीडियो कभी नहीं भेजा जाता — केवल एक संख्यात्मक चेहरा हस्ताक्षर।",
  "Your face registration request has been sent to HR for approval. You'll be notified once it's reviewed.": "आपका चेहरा पंजीकरण अनुरोध एचआर को स्वीकृति के लिए भेज दिया गया है। समीक्षा होने पर आपको सूचित किया जाएगा।",
  "Low light detected — your screen is now acting as a light. Raising your screen brightness helps.": "कम रोशनी का पता चला — आपकी स्क्रीन अब रोशनी का काम कर रही है। स्क्रीन की चमक बढ़ाने से मदद मिलेगी।",
  "Please allow camera access in the browser prompt to punch in or out.": "पंच इन या आउट करने के लिए कृपया ब्राउज़र प्रॉम्प्ट में कैमरा एक्सेस की अनुमति दें।",
  "Preparing face verification": "चेहरा सत्यापन तैयार हो रहा है",
  "Verify Your Identity": "अपनी पहचान सत्यापित करें",
  "We couldn't get a reliably clear capture to verify against your registered face. Try better lighting and hold steady.": "आपके पंजीकृत चेहरे से मिलान के लिए हमें भरोसेमंद रूप से साफ़ कैप्चर नहीं मिल सका। बेहतर रोशनी में कोशिश करें और स्थिर रहें।",
  "We didn't detect a slight head turn in time. Make sure you're well-lit and centered, then try again.": "हमें समय पर सिर का हल्का घुमाव नहीं दिखा। सुनिश्चित करें कि पर्याप्त रोशनी हो और आप फ़्रेम के बीच में हों, फिर फिर कोशिश करें।",
  "Your account requires face verification to punch in or out. Allow camera access for this site in your browser's settings, then try again.": "आपके खाते में पंच इन या आउट के लिए चेहरा सत्यापन आवश्यक है। अपने ब्राउज़र की सेटिंग्स में इस साइट के लिए कैमरा एक्सेस की अनुमति दें, फिर फिर कोशिश करें।",
