  "Allow camera access for this site in your browser's settings, then try again — or upload a photo from your device instead.": "अपने ब्राउज़र की सेटिंग्स में इस साइट के लिए कैमरा एक्सेस की अनुमति दें, फिर फिर कोशिश करें — या इसके बजाय अपने डिवाइस से फ़ोटो अपलोड करें।",
  "Capture": "कैप्चर करें",
