  "Choose a JPG or PNG from your device to continue.": "आगे बढ़ने के लिए अपने डिवाइस से JPG या PNG चुनें।",
  "Choose Another": "दूसरी चुनें",
  "JPG, JPEG, or PNG — resized automatically to fit. Choose one photo, or capture a new one with your camera.": "JPG, JPEG या PNG — अपने आप सही आकार में बदल जाती है। एक फ़ोटो चुनें, या कैमरे से नई फ़ोटो लें।",
