  "{count} position selected": "{count} पद चुना गया",
  "{count} positions selected": "{count} पद चुने गए",
  "Any permission a selected position already has that isn't part of": "चुने गए पद के पास पहले से मौजूद कोई भी अनुमति जो इसका हिस्सा नहीं है:",
  "Apply": "लागू करें",
  "applying this": "इसे लागू करने पर",
  "below will be removed. This can't be undone automatically — you'd have to re-set it manually afterward.": "नीचे दी गई हटा दी जाएगी। इसे अपने आप वापस नहीं किया जा सकता — बाद में आपको इसे हाथ से दोबारा सेट करना होगा।",
  "Confirm applying": "लागू करने की पुष्टि करें",
