  "Annual fixed CTC must be greater than zero, or left blank.": "वार्षिक निश्चित CTC शून्य से अधिक होना चाहिए, या खाली छोड़ें।",
  "Date of birth cannot be in the future.": "जन्म तिथि भविष्य में नहीं हो सकती।",
