  "Enter a valid alternate Indian mobile number — it must start with 6-9.": "मान्य वैकल्पिक भारतीय मोबाइल नंबर दर्ज करें — यह 6-9 से शुरू होना चाहिए।",
  "Enter a valid alternate mobile number, or leave it blank.": "मान्य वैकल्पिक मोबाइल नंबर दर्ज करें, या खाली छोड़ें।",
  "Enter a valid IFSC code (format: HDFC0001234).": "मान्य IFSC कोड दर्ज करें (प्रारूप: HDFC0001234)।",
