  "Enter a valid mobile number.": "मान्य मोबाइल नंबर दर्ज करें।",
  "Enter a valid PAN (format: ABCDE1234F).": "मान्य PAN दर्ज करें (प्रारूप: ABCDE1234F)।",
  "Enter a valid work email address.": "मान्य कार्य ईमेल पता दर्ज करें।",
  "First name can only contain letters, spaces, hyphens and apostrophes.": "पहले नाम में केवल अक्षर, रिक्त स्थान, हाइफ़न और एपॉस्ट्रोफ़ी हो सकते हैं।",
  "First name is required.": "पहला नाम आवश्यक है।",
