  "Last name can only contain letters, spaces, hyphens and apostrophes.": "अंतिम नाम में केवल अक्षर, रिक्त स्थान, हाइफ़न और एपॉस्ट्रोफ़ी हो सकते हैं।",
  "Last name is required.": "अंतिम नाम आवश्यक है।",
  "Middle name can only contain letters, spaces, hyphens and apostrophes.": "मध्य नाम में केवल अक्षर, रिक्त स्थान, हाइफ़न और एपॉस्ट्रोफ़ी हो सकते हैं।",
